import{z as o,x as M,o as t,c as p,q as r,j as S,D as s,d as l,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"MSS 与钳制","description":"","frontmatter":{"title":"MSS 与钳制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mss-clamping.md","filePath":"cs/mss-clamping.md","lastUpdated":1791063341000}'),A={name:"cs/mss-clamping.md"};function d(T,a,P,m,B,C){const E=M("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="mss-与钳制" tabindex="-1">MSS 与钳制 <a class="header-anchor" href="#mss-与钳制" aria-label="Permalink to &quot;MSS 与钳制&quot;">​</a></h1><div class="epigraph"><p>MSS 是对端愿意收的最大段；路径更小时应 PMTUD，边缘用钳制改 SYN 里的 MSS，是权宜，会把整条连接钉死在保守值。</p><footer>—— 据 RFC 9293 TCP；RFC 6691 MSS 与 IP 选项；RFC 4821 对照整理</footer></div><p><a href="/cs/pmtud">PMTUD</a> 与 <a href="/cs/jumbo-mtu">巨帧</a> 已给路径最小。<a href="/cs/window-scale-timestamps">上一课</a> 放大窗口。缺口是 <strong>MSS 选项与 MSS clamping</strong>：隧道口、PPPoE、VLAN 如何在 SYN 上减 40。本课不把 TCP 状态图画完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>段太大则分片或黑洞。主机按本机 MTU 广告 MSS（IPv4 常 MTU−40）。中间看不到数据 MTU 时，用钳制把 SYN/SYN-ACK 的 MSS 改小，强迫两端用小段，避开 ICMP。代价：即使路径能 9000，连接仍 1460；TSO 后课会在网卡再切。IPv6 钳制同样存在。GRE/VXLAN 边缘最爱用。</p><p>不要把 MSS 写成 MTU：MSS 是 TCP 载荷，MTU 是 IP 包。</p><p><span class="marginnote">数字实例：以太网 MTU 1500，减去 IPv4 头 20 字节再减 TCP 头 20 字节，得 MSS=1460；若走 PPPoE 还要多 8 字节封装，MTU 掉到 1492，MSS 就只剩 1452。所谓「在 SYN 上减 40」就是这道减法。</span></p><p><span class="marginnote">RFC 9293。钳制是运营技巧，不是 TCP 状态机一步。本课不鼓励在核心乱改包。</span></p><h3 id="mss-不是-mtu" tabindex="-1">MSS 不是 MTU <a class="header-anchor" href="#mss-不是-mtu" aria-label="Permalink to &quot;MSS 不是 MTU&quot;">​</a></h3><p>钳制改 SYN，避开黑洞也钉死段大小。优先统一 MTU 或真 PMTUD。乱钳到 536 会毁掉现代网。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：PMTUD 动态 vs 钳制定静态。画：SYN MSS=9000 → 边缘改 1420 → 全程小段。与 BDP：小 MSS 使每 RTT 加一更细，但也更多头税。</p>',12)),(t(),S(n,null,{default:s(()=>[i(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADV%5B%22%E5%B9%BF%E5%91%8A%20MSS%22%5D%20--%3E%20PATH%5B%22%E7%9C%9F%E5%AE%9E%E8%B7%AF%E5%BE%84%20MTU%22%5D%0A%20%20PATH%20--%3E%20PMTU%5B%22PMTUD%22%5D%0A%20%20ADV%20--%3E%20CLAMP%5B%22%E8%BE%B9%E7%BC%98%E9%92%B3%E5%88%B6%20SYN%22%5D%0A%20%20CLAMP%20--%3E%20SMALL%5B%22%E8%BF%9E%E6%8E%A5%E9%92%89%E5%9C%A8%E5%B0%8F%E6%AE%B5%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"快重传按段计；MSS 变，三个 dupACK 的字节数变。RoCE 用自己的 MTU，不借 MSS。QUIC 用 PMTUD/PLPMTUD 在 UDP 上。安全：钳制可被中间人用来降效，与 ICMP 缩小同类，需信任边缘。",-1)),a[5]||(a[5]=e("p",null,"数据中心统一 MTU 则少钳制。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为钳制要拆包重装整个报文，实际上它只改 SYN 头里 2 字节的 MSS 选项数值，数据包原样转发——所以几乎零开销，但也正因为只看 SYN，它对之后路径 MTU 的变化毫无反应。")],-1)),(t(),S(n,null,{default:s(()=>[i(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYN%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%20SYN%20%E5%B8%A6%20MSS%201460%22%5D%20--%3E%20EDGE%5B%22PPPoE%20%E8%BE%B9%E7%BC%98%E8%AE%BE%E5%A4%87%22%5D%0A%20%20EDGE%20--%3E%20M%5B%22%E6%9C%AC%E5%8F%A3%20MTU%20%E5%8F%AA%E6%9C%89%201492%22%5D%0A%20%20M%20--%3E%20R%5B%22%E9%87%8D%E5%86%99%20MSS%20%E4%B8%BA%201492%20%E5%87%8F%2040%20%E5%8D%B3%201452%22%5D%0A%20%20R%20--%3E%20ACK%5B%22%E5%AF%B9%20SYN-ACK%20%E5%81%9A%E5%90%8C%E6%A0%B7%E9%92%B3%E5%88%B6%22%5D%0A%20%20ACK%20--%3E%20CONN%5B%22%E6%95%B4%E6%9D%A1%E8%BF%9E%E6%8E%A5%E5%8F%AA%E7%94%A8%201452%20%E5%AD%97%E8%8A%82%E8%BD%BD%E8%8D%B7%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">直觉类比：钳制像在高速入口给大货车换一张「限载 40 吨」的新路条——货车本身没动，只是此后整趟都按小额度走；哪怕前路其实能跑 60 吨，这张连接的路条也改不回来了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 TCP 分段卸载的全部。TCP 状态机是下一课。后课默认：MSS 来自对端与路径；钳制是边缘补丁。</p><p>把 MSS 钳到 536「为了兼容」会毁掉现代网。</p><p>下一课<a href="/cs/tcp-state-machine">TCP 状态机</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MSS 约束 TCP 段，关系是 MTU 减头。</li><li>钳制改 SYN，避开黑洞也钉死大小。</li><li>优先统一 MTU 或真 PMTUD。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9293；RFC 4821。</li></ul>',7))])}const h=o(A,[["render",d]]);export{c as __pageData,h as default};
